/* BreatheEasy: SYNTHETIC demo check-ins so judges can watch the model learn.
 * Every entry is generated by a seeded random process below and flagged `synthetic: true`.
 * It is NOT real patient data and is never mixed into a real user's log without a label.
 * The hidden "true" pattern is chosen for the demo: this made-up person is sensitive to
 * ozone and pollen, mildly to heat, and not to humidity. A working model should recover that.
 */
(function (root) {
  'use strict';

  function mulberry32(seed) {
    return function () {
      seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
      var t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function addDays(iso, n) {
    var d = new Date(iso + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10);
  }

  /** endDate: last day (ISO). days: how many. personalBest: peak-flow best for the demo person. */
  function generate(endDate, days, personalBest, seed) {
    var rnd = mulberry32(seed == null ? 42 : seed);
    days = days || 75; personalBest = personalBest || 400;
    var out = [], prevBad = 0;
    for (var i = days - 1; i >= 0; i--) {
      var date = addDays(endDate, -i);
      var hotSpell = Math.sin((days - i) / 9) > 0.3 ? 1 : 0;
      var aqiO3 = Math.round(Math.max(15, Math.min(185, 55 + 45 * hotSpell + (rnd() - 0.5) * 80)));
      var aqiPM25 = Math.round(Math.max(20, Math.min(110, 45 + (rnd() - 0.5) * 50)));
      var pollenLevel = Math.floor(rnd() * 4); // 0..3
      var tempMaxF = Math.round(78 + 12 * hotSpell + (rnd() - 0.5) * 12);
      var humidity = Math.round(55 + (rnd() - 0.5) * 40);
      var logit = -1.2 + 0.035 * (aqiO3 - 60) + 0.75 * (pollenLevel - 1) + 0.05 * (tempMaxF - 82) + 0.9 * prevBad;
      var p = 1 / (1 + Math.exp(-logit));
      var bad = rnd() < p ? 1 : 0;
      var pct = bad ? (rnd() < 0.15 ? 45 + Math.floor(rnd() * 5) : 60 + Math.floor(rnd() * 19)) : 82 + Math.floor(rnd() * 18);
      var zone = pct >= 80 ? 'green' : pct >= 50 ? 'yellow' : 'red';
      var symptoms = zone === 'green' ? [] : zone === 'yellow' ? [['cough', 'wheeze', 'chest_tight'][Math.floor(rnd() * 3)]] : ['very_short_breath'];
      out.push({
        date: date, synthetic: true,
        peakFlow: Math.round(personalBest * pct / 100), personalBest: personalBest, percent: pct,
        symptoms: symptoms, zone: zone, reliever: zone !== 'green',
        aqiO3: aqiO3, aqiPM25: aqiPM25, pollenLevel: pollenLevel, tempMaxF: tempMaxF, humidity: humidity
      });
      prevBad = bad && zone !== 'green' ? 1 : 0;
    }
    return out;
  }

  var api = { generate: generate, mulberry32: mulberry32, addDays: addDays };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.BE_Demo = api;
})(this);
